// Drag from the dot of `from` nearest `to`, capturing a frame every few steps when `frames` is given.
const drag = async (ctx, from, to, frames) => {
  const { client, json } = ctx;
  const m = (type, x, y, extra = {}) => client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });
  const c0 = await client.evaluate(`const ed = window.__dgEd; const b = ed.getShapePageBounds(${json(from)}); return ed.pageToScreen({ x: b.midX, y: b.midY });`);
  await m("mouseMoved", c0.x, c0.y, { button: "none" });
  await m("mousePressed", c0.x, c0.y, { buttons: 1 });
  await m("mouseReleased", c0.x, c0.y);
  await sleep(400);
  if (frames) await frames.add("select", 2);
  const { start, target } = await client.evaluate(`
    const ed = window.__dgEd;
    const b = ed.getShapePageBounds(${json(to)});
    const target = ed.pageToScreen({ x: b.midX, y: b.midY });
    const dots = [...ed.getContainer().querySelectorAll(".cursor-crosshair")].map((d) => {
      const r = d.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; });
    dots.sort((a, c) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(c.x - target.x, c.y - target.y));
    return { start: dots[0], target };`);
  if (!start) throw new Error("no drag dots");
  await m("mouseMoved", start.x, start.y, { button: "none" });
  await m("mousePressed", start.x, start.y, { buttons: 1 });
  const N = 16;
  for (let i = 1; i <= N; i++) {
    const t = i / N;
    await m("mouseMoved", start.x + (target.x - start.x) * t, start.y + (target.y - start.y) * t, { buttons: 1 });
    await sleep(25);
    if (frames && i % 3 === 0) await frames.add("drag", 0.12);
  }
  await m("mouseReleased", target.x, target.y);
  await sleep(500);
};

// Frame recorder: PNGs plus an ffmpeg concat list with per-frame durations (seconds).
const recorder = (name) => {
  const dir = `${OUT}${name}/`;
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
  let n = 0;
  const list = [];
  return {
    ctx: null,
    async add(_label, dur) {
      const f = `f${String(++n).padStart(3, "0")}.png`;
      await hideNotices(this.ctx);
      const r = await clipRect(this.ctx);
      const { data } = await this.ctx.client.send("Page.captureScreenshot", { format: "png", clip: { ...r, scale: 1 } });
      fs.writeFileSync(dir + f, Buffer.from(data, "base64"));
      list.push(`file '${f}'\nduration ${dur}`);
    },
    done() {
      const last = list[list.length - 1].split("\n")[0];
      fs.writeFileSync(dir + "list.txt", list.join("\n") + "\n" + last + "\n");
      return n;
    },
  };
};

