  await mouse(ctx.client, "mouseMoved", a.x, a.y, { button: "none" });
  await mouse(ctx.client, "mousePressed", a.x, a.y, { buttons: 1 });
  const N = 16;
  for (let i = 1; i <= N; i++) {
