        bars.forEach(([l, v, c], i) => { const x = 170 + i * 220; g.fillStyle = c; g.fillRect(x, 330 - v * 2.5, 120, v * 2.5);
          g.fillStyle = "#222"; g.font = "bold 22px sans-serif"; g.fillText(v + "%", x + 60, 330 - v * 2.5 - 10);
          g.font = "20px sans-serif"; g.fillText(l, x + 60, 360); });
        const buf = await (await new Promise((r) => cv.toBlob(r, "image/png"))).arrayBuffer();
        const f = app.vault.getAbstractFileByPath(${ctx.json(CHART)});
        if (f) await app.vault.modifyBinary(f, buf); else await app.vault.createBinary(${ctx.json(CHART)}, buf);
        const note = app.vault.getAbstractFileByPath(${ctx.json(EVD_NOTE)});
        const body = await app.vault.read(note);
        if (!body.includes("sleep-recall-chart.png")) await app.vault.modify(note, body.trimEnd() + "\\n\\n![[sleep-recall-chart.png]]\\n");
        const p = ${P(ctx)};
        p.settings.nodeTypes.find((n) => n.name === "Evidence").keyImage = true;
        await p.saveSettings();
        await new Promise((r) => setTimeout(r, 600));
        const ed = window.__dgEd;
        ed.updateShapes([{ id: ${ctx.json(E)}, type: "discourse-node", x: 1 }]);
        ed.updateShapes([{ id: ${ctx.json(E)}, type: "discourse-node", x: 0 }]);
        return true;
      })();`);
      await ctx.client.waitFor(`return !!window.__dgEd.getShape(${ctx.json(E)}).props.imageSrc;`, { label: "imageSrc set", timeout: 8000 });
      await sleep(1500);
      await ctx.client.evaluate(`window.__dgEd.selectNone(); return true;`);
      await sleep(300);
      const s = await ctx.client.evaluate(`const s = window.__dgEd.getShape(${ctx.json(E)}); return { w: s.props.w, h: s.props.h, img: !!s.props.imageSrc, rendered: !!window.__dgEd.getContainer().querySelector("img") };`);
      await shotCanvas(ctx, "key-figure-example-raw.png");
      return s;
    },
    expect: (o) => ({ pass: o.img && o.rendered, actual: JSON.stringify(o) }),
    teardown: async (ctx, s) => {
      await restoreAll(ctx, s);
      await sleep(400);
      await ctx.client.evaluate(`const ed = window.__dgEd; const sh = ed.getShape(${ctx.json(E)}); ed.updateShapes([{ id: sh.id, type: sh.type, props: { imageSrc: undefined } }]); return true;`);
      await sleep(800);
    },
  },
  {
    name: "open-canvas-command",
    input: "markdown view; command palette 'switch to canvas'",
    expected: "Switch to Discourse Graph canvas view listed",
    run: async (ctx) => {
      await docsPrepare(ctx);
      await ctx.client.evaluate(`return (async () => {
        const leaf = app.workspace.getLeavesOfType("tldraw-dg-preview").find((l) => l.view.file?.path?.endsWith("Sleep and memory.md"));
        await leaf.setViewState({ type: "markdown", state: leaf.view.getState() });
        app.workspace.setActiveLeaf(leaf, { focus: true });
        await new Promise((r) => setTimeout(r, 500));
        app.commands.executeCommandById("command-palette:open");
        return true;
      })();`);
      await ctx.client.waitFor(`return !!document.querySelector(".prompt input");`, { label: "palette" });
      await sleep(200);
      for (const ch of "switch to canvas") { await ctx.client.typeText(ch); await sleep(30); }
      await sleep(500);
      const r = await ctx.client.evaluate(`const p = document.querySelector(".prompt").getBoundingClientRect(); return { x: p.left - 16, y: p.top - 16, width: p.width + 32, height: p.height + 32 };`);
      const items = await ctx.client.evaluate(`return [...document.querySelectorAll(".prompt .suggestion-item")].map((s) => s.textContent.trim());`);
      await shotRect(ctx, "open-canvas-command.png", r);
      await ctx.client.pressEscape();
      await ctx.client.evaluate(`return (async () => {
        const leaf = app.workspace.getLeavesOfType("markdown").find((l) => l.view.file?.path?.endsWith("Sleep and memory.md"));
        if (leaf) await leaf.setViewState({ type: "tldraw-dg-preview", state: leaf.view.getState() });
        return true;
      })();`);
      return { items };
    },
    expect: (o) => ({ pass: o.items.some((i) => i.includes("Switch to Discourse Graph canvas view")), actual: JSON.stringify(o) }),
  },
];

export default only ? scenarios.filter((s) => only.includes(s.name)) : scenarios;

